VALUES (808, 'chuot-logitech-g102-lightsync-rgb-black', N'Chuột Logitech G102 LightSync Black', N'https://product.hstatic.net/200000722513/product/logitech-g102-lightsync-rgb-black-1_bf4f5774229c4a0f81b8e8a2feebe4d8_aeb4ae49ee844c3e9d315883d4e482d4.jpg,https://product.hstatic.net/200000722513/product/logitech-g102-lightsync-rgb-black-2_7788492f5ed748248bd8cb2e967f9cc3_705d7bb9777440eab14aedb8e3975545.jpg', 4050.0, 360, N'##Đánh giá chi tiết chuột Logitech G102 Lightsync RGB BlackDù có mức giá rất bình dân nhưng&nbsp;chuột Logitech&nbsp;G102 Lightsync RGB&nbsp;lại được trang bị led&nbsp; RGB 16,8 triệu màu .Chọn một màu hay trộn 3 màu, hiệu ứng có sẵn&nbsp;hay tạo hiệu ứng của riêng bạn . Sự lựa chọn là của bạn !&nbsp;Bạn&nbsp;còn có thể đồng bộ chuột với thiết bị LIGHTSYNC của Logitech G khác giúp góc máy&nbsp;trở nên đồng bộ và&nbsp;độc đáo hơn.Cảm biến cấp độ chơi gameTheo dõi con trỏ chính xác và đạt hiệu suấ', N'Logitech - Chuột', N'{"hl_pin": "Không", "hl_connect": "Có dây", "hl_prod": "bestseller", "hl_gift": "0", "hl_led": "Led RGB", "hl_price": "599000", "hl_banchay": "yes", "hl_fs-mouse": "no", "spec_Tình Trạng": "Mới 100% - Fullbox", "spec_Độ dài dây (cm) ": "210", "spec_Led": "RGB", "spec_Số lượng nút bấm": " 6", "spec_Bảo hành": "24 tháng", "spec_Điểm ảnh trên 1 inch (DPI)": "8000", "spec_Mắt đọc  ": "Mercury Sensor", "spec_Kết nối": "USB", "spec_Kích thước (mm)": "Dài 116.6 x Rộng 62.15 x Cao 38.2", "spec_Tần số ph', 1, 1, 0, NULL, 30, GETDATE(), GETDATE(), 0);
