VALUES (822, 'chuot-logitech-g102-lightsync-rgb-white', N'Chuột Logitech G102 LightSync White', N'https://product.hstatic.net/200000722513/product/logitech-g102-lightsync-rgb-white-1_eb113ff7e83b4289812fb9bff7034b4d_581b766edc6e402e995fd81477456742.jpg,https://product.hstatic.net/200000722513/product/logitech-g102-lightsync-rgb-white-2_5825855084a9400ab038d02a5e7ece14_dd77f9fe14814a698244c0bfa840ff0d.jpg,https://product.hstatic.net/200000722513/product/logitech-g102-lightsync-rgb-white-3_1c4ea7b6462548d780ca23541fab3ef6_ff6deca7dfdc4567a89ee7e5bc5edc2d.jpg', 4150.0, 29, N'##Dù có mức giá rất bình dân nhưng&nbsp;Chuột Logitech&nbsp;G102 Lightsync RGB&nbsp;lại được trang bị led&nbsp; RGB 16,8 triệu màu .Chọn một màu hay trộn 3 màu, hiệu ứng có sẵn&nbsp;hay tạo hiệu ứng của riêng bạn . Sự lựa chọn là của bạn !&nbsp;Bạn&nbsp;còn có thể đồng bộ chuột với thiết bị LIGHTSYNC của Logitech G khác giúp góc máy&nbsp;trở nên đồng bộ và&nbsp;độc đáo hơn.Cảm biến cấp độ chơi gameTheo dõi con trỏ chính xác và đạt hiệu suất phản hồi nhanh nhạy nhờ vào cảm biến cấp độ chơi game. ', N'Logitech - Chuột', N'{"hl_pin": "Không", "hl_connect": "Có dây", "hl_prod": "bestseller", "hl_gift": "0", "hl_ship": "0", "hl_led": "Led RGB", "hl_price": "599000", "hl_fs-time1": "no", "hl_fs-time2": "no", "hl_fs-time4": "no", "hl_fs-time1-1": "no", "hl_fs-mon-gear": "no", "hl_fs-mon-time3": "no", "hl_fs-time3": "no", "hl_fs-tue-gear": "no", "hl_fs-sat-mouse": "no", "hl_flashsale": "no", "hl_fs-mouse": "no", "spec_Switch": "Omron", "spec_IPS": "200", "spec_Độ dài dây (cm)\t": "210", "spec_LED": "RGB Lightsync", "sp', 1, 1, 0, NULL, 30, GETDATE(), GETDATE(), 0);
